                        FLAC__stream_encoder_get_state(e->encoder) == FLAC__STREAM_ENCODER_VERIFY_MISMATCH_IN_AUDIO_DATA
                ;
        }
        /* all errors except verify errors should interrupt the stats */
        if(ret && !verify_error)
                print_error_with_state(e, "ERROR during encoding");
